from collections import deque
from typing import List

def shortestDistance(N: int, M: int, X: int, Y: int, A: List[List[int]]) -> int:
    if A[0][0] == 0:
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])
    visited = set((0, 0))

    while queue:
        x, y, steps = queue.popleft()
        if x == X and y == Y:
            return steps
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and A[nx][ny] == 1 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1
